tokenization.pseudocode:
class TokenVault:  # 원본은 금고(토큰 서버)에만 보관
    def __init__(self):
        self.store = {}  # token → 암호화된 원본

    def tokenize(self, pan):
        while True:  # 원본과 수학적 관계 없는 난수 토큰
            token = pan[:6] + random_digits(6) + pan[-4:]
            if token not in self.store and token != pan:
                break
        self.store[token] = encrypt(pan)
        return token  # 형식 보존: 16자리 숫자 유지

    def detokenize(self, token, caller):
        if not authorized(caller):  # 금고 접근 통제
            raise PermissionError('권한 없음')
        return decrypt(self.store[token])

# 가맹점 DB에는 토큰만 저장 → PCI DSS 범위 축소
# 암호화와 달리 키로 역산 불가, 금고 조회로만 복원

topic-modeling.pseudocode:
def lda_gibbs(docs, K, V, alpha, beta, iters):
    # docs: 단어 ID 리스트들, K: 토픽 수, V: 어휘 크기
    ndk = [[0] * K for _ in docs]  # 문서-토픽 빈도
    nkw = [[0] * V for _ in range(K)]  # 토픽-단어 빈도
    nk = [0] * K
    z = [[randrange(K) for _ in doc] for doc in docs]
    def count(d, w, k, c):
        ndk[d][k] += c
        nkw[k][w] += c
        nk[k] += c
    for d, doc in enumerate(docs):
        for i, w in enumerate(doc):
            count(d, w, z[d][i], 1)
    for _ in range(iters):
        for d, doc in enumerate(docs):
            for i, w in enumerate(doc):
                count(d, w, z[d][i], -1)  # 현재 할당 제외
                p = [(ndk[d][k] + alpha)
                     * (nkw[k][w] + beta)
                     / (nk[k] + V * beta) for k in range(K)]
                z[d][i] = sample_index(p)  # 비례 확률로 재샘플
                count(d, w, z[d][i], 1)
    return ndk, nkw

topological-sort.pseudocode:
def topo_sort(graph):  # Kahn 알고리즘, O(V+E)
    indeg = {v: 0 for v in graph}
    for u in graph:
        for v in graph[u]:
            indeg[v] += 1
    queue = [v for v in graph if indeg[v] == 0]
    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in graph[u]:  # u의 나가는 간선 제거
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    if len(order) < len(graph):
        return None  # 순환 존재 -> 위상정렬 불가
    return order

tournament-selection.pseudocode:
def tournament_select(population, fitness, k):
    contenders = random_sample(population, k)  # 무작위 k개
    return max(contenders, key=fitness)  # 그중 최우수 1개

def select_parents(population, fitness, k, n):
    # 토너먼트를 n번 독립 수행 → 병렬화 용이
    return [tournament_select(population, fitness, k)
            for _ in range(n)]
# k=1이면 무작위 선택, k=집단 크기면 항상 최우수
